#!/usr/bin/env node
/* eslint-disable no-console */
const fs = require('fs');
const path = require('path');

const REPO_ROOT = path.resolve(__dirname, '..');
const SRC_CPP   = path.join(REPO_ROOT, '/src/cpp');
const NITRO_JSON_PATH = path.join(REPO_ROOT, '/nitro.json');

const GENERATED_BANNER =
  '// AUTO-GENERATED FILE — DO NOT EDIT.\n' +
  '// Generated by scripts/generate-testnet-variants.cjs\n';

const DEFINE_TESTNET = '#define testnet 1\n';

// ---------------- helpers ----------------

function readJson(file) {
  const txt = fs.readFileSync(file, 'utf8');
  return JSON.parse(txt);
}

function writeJson(file, obj) {
  const txt = JSON.stringify(obj, null, 2) + '\n';
  fs.writeFileSync(file, txt, 'utf8');
}

function listCppFiles(dir) {
  /** return absolute paths of .hpp/.cpp under dir (non-recursive + recursive) */
  const out = [];
  function walk(d) {
    for (const entry of fs.readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, entry.name);
      if (entry.isDirectory()) walk(p);
      else if (/\.(hpp|cpp)$/.test(entry.name)) out.push(p);
    }
  }
  walk(dir);
  return out;
}

function withTestnetSuffix(filePath) {
  const dir = path.dirname(filePath);
  const ext = path.extname(filePath);
  const base = path.basename(filePath, ext);
  if (base.endsWith('Testnet')) return filePath; // already a testnet file
  return path.join(dir, `${base}Testnet${ext}`);
}

// Build a word-boundary alternation from class names
function buildAlternation(names) {
  // escape special regex chars just in case
  const esc = s => s.replace(/[-/\\^$*+?.()|[\]{}]/g, '\\$&');
  return `\\b(${names.map(esc).join('|')})\\b`;
}

function replaceAll(content, pattern, replacement) {
  const re = new RegExp(pattern, 'g');
  return content.replace(re, replacement);
}

// ---------------- main ----------------

function main() {
  // 1) Read nitro.json and fetch autolinking entries { Key: { cpp: "HybridX" }, ... }
  const nitro = readJson(NITRO_JSON_PATH);

  if (!nitro.autolinking || typeof nitro.autolinking !== 'object') {
    console.error(`❌ Could not find an object at "autolinking" in ${NITRO_JSON_PATH}.`);
    process.exit(1);
  }

  const linkMap = nitro.autolinking; // e.g., { Account: { cpp: "HybridAccount" }, ... }
  const entries = Object.entries(linkMap).filter(([k, v]) => v && typeof v.cpp === 'string');
  if (entries.length === 0) {
    console.error(`❌ No autolinking entries with a "cpp" field found in ${NITRO_JSON_PATH}.`);
    process.exit(1);
  }

  // Collect base hybrid C++ class names (without Testnet suffix)
  const baseHybridClasses = Array.from(new Set(entries
    .map(([, v]) => v.cpp)
    .filter((name) => typeof name === 'string' && !name.endsWith('Testnet'))));

  const testnetHybridClasses = baseHybridClasses.map(n => `${n}Testnet`);

  // 2) Update nitro.json: ensure Testnet variants exist alongside originals
  let added = 0;
  for (const [key, val] of entries) {
    const baseCpp = val.cpp;
    if (!baseCpp || baseCpp.endsWith('Testnet')) continue;

    const testKey = `${key}Testnet`;
    const testCpp = `${baseCpp}Testnet`;
    if (!linkMap[testKey]) {
      linkMap[testKey] = { cpp: testCpp };
      added++;
    } else if (!linkMap[testKey].cpp) {
      linkMap[testKey].cpp = testCpp;
      added++;
    }
  }

  if (added > 0) {
    writeJson(NITRO_JSON_PATH, nitro);
    console.log(`✅ Updated nitro.json: added/updated ${added} Testnet autolinking entries.`);
  } else {
    console.log(`ℹ️ nitro.json already contains Testnet variants for all hybrids.`);
  }

  // 3) Duplicate every .cpp/.hpp in src/cpp → *Testnet.cpp/.hpp and transform contents
  const files = listCppFiles(SRC_CPP)
    .filter(p => !path.basename(p).includes('Testnet')); // don’t reprocess generated files

  if (files.length === 0) {
    console.log(`ℹ️ No .cpp/.hpp files found under ${SRC_CPP}`);
    return;
  }

  // Regexes
  const classAlt = buildAlternation(baseHybridClasses);
  const includeFind = new RegExp(
    // #include "HybridX.hpp" or angle-includes; we handle quotes
    String.raw`(#\s*include\s*")(${baseHybridClasses.map(n => n.replace(/[-/\\^$*+?.()|[\]{}]/g,'\\$&')).join('|')})(\.h(?:pp)?)(")`,
    'g'
  );
  const classRefFind = new RegExp(classAlt, 'g');

  let generatedCount = 0;

  for (const file of files) {
    const outFile = withTestnetSuffix(file);
    const orig = fs.readFileSync(file, 'utf8');

    // Transform content:
    let txt = orig;

    // 3a) Add banner + define at very top
    txt = GENERATED_BANNER + DEFINE_TESTNET + '\n' + txt;

    // 3b) Rewire includes to Testnet headers for hybrid classes
    //     e.g., #include "HybridProgram.hpp" -> #include "HybridProgramTestnet.hpp"
    txt = txt.replace(includeFind, (m, a, name, ext, d) => `${a}${name}Testnet${ext}${d}`);

    // 3c) Rename class/type references for hybrid classes only
    //     e.g., HybridProgram -> HybridProgramTestnet
    txt = txt.replace(classRefFind, (name) => `${name}Testnet`);

    // 3d) Switch Rust FFI namespace
    txt = replaceAll(txt, String.raw`\bshield_mainnet::`, 'shield_testnet::');

    // 3e) Also fix explicit rust bridge include if present
    txt = txt.replace(
      /(#\s*include\s*")rust\/shield_mainnet\.h(")/g,
      '$1rust/shield_testnet.h$2'
    );

    txt = txt.replace(
      /\bHybridObject\s*\(\s*TAG\s*\)/g,
      `HybridObject([]() -> const char* { static std::string k = std::string(TAG) + "Testnet"; return k.c_str(); }())`
    );
    txt = txt.replace(
      /\bHybridObject\s*\(\s*::\s*TAG\s*\)/g,
      `HybridObject([]() -> const char* { static std::string k = std::string(TAG) + "Testnet"; return k.c_str(); }())`
    );
    // Ensure destination directory exists
    fs.mkdirSync(path.dirname(outFile), { recursive: true });
    fs.writeFileSync(outFile, txt, 'utf8');
    generatedCount++;
    console.log(`++ Generated ${path.relative(REPO_ROOT, outFile)}`);
  }

  console.log(`\n✅ Done. Generated ${generatedCount} Testnet files and updated nitro.json.`);
}

main();
